import {itemName} from './progression.js';
export function shopScreen({data,race,esc,btn,tab='supplies',saleSelection=[]}){
 const g=race.state,black=g.event===data.economy.market.blackEvent;
 if(!race.canShop())return '<p>SBR 대회 보급소에 도착했을 때 이용할 수 있습니다.</p>';
 const kinds={supplies:['heal','supply'],gear:['gear'],service:['tune','service']},rows=race.shop();
 const visible=rows.filter(r=>(black?['rare']:kinds[tab]||kinds.supplies).includes(r.kind));
 const tabs=`<nav class="shop-tabs${black?' shop-tabs-rare':''}" aria-label="상점 분류">${(black?[['gear','한정 물품'],['sell','판매']]:[['supplies','물자'],['gear','무기·장비'],['service','정비'],['sell','판매']]).map(([key,label])=>btn('shop-tab:'+key,label,(black&&tab==='supplies'&&key==='gear'||tab===key)?'active':'',`aria-pressed="${black&&tab==='supplies'&&key==='gear'||tab===key}"`)).join('')}</nav>`;
 if(tab==='sell'){
  const sale=race.sellable(),chosen=sale.filter(r=>saleSelection.includes(r.id)&&!r.reason),sum=chosen.reduce((n,r)=>n+r.price,0),lower=race.inferiorSales(),list=sale.map(r=>`<article class="shop-row" data-item="sell_${esc(r.id)}"><div class="shop-copy"><div class="shop-item-title"><button class="sale-check" data-action="sale-select:${esc(r.id)}" aria-pressed="${chosen.some(x=>x.id===r.id)}" aria-label="${esc(r.n)} 판매 선택" ${r.reason?'disabled':''}>${chosen.some(x=>x.id===r.id)?'✓':'선택'}</button><b>${esc(r.n)}</b><span class="slot-tag">${esc(r.kind==='supply'?'소모품':data.equipmentSlots[r.slot])}</span></div><p>${esc(r.d)}</p><small class="shop-note">보유 ${r.count}개 · 기준가 $${r.retail} · 매입가 $${r.price}</small>${r.reason?`<small class="shop-status">${esc(r.reason)}</small>`:''}</div><div class="shop-buy">${btn('sell-item:'+r.id,`<b>+$${r.price}</b><span>1개 판매</span>`,'purchase',`${r.reason?'disabled':''} aria-label="${esc(r.n)} 1개 판매 $${r.price}"`)}</div></article>`).join('');
  return `<div class="shop-topline"><span>보유 물품 판매</span><strong>$${g.ch.money}</strong></div>${tabs}<div class="sale-tools">${btn('sale-inferior','하위 일반 장비 선택 · '+lower.length+'개','quiet',lower.length?'':'disabled')}${btn('sale-clear','선택 해제','quiet',chosen.length?'':'disabled')}${btn('sale-confirm','선택품 '+chosen.length+'개 판매 · +$'+sum,'',chosen.length?'':'disabled')}</div><p class="shop-provider">현재 기준 구매가의 50%에 매입합니다. 소수점은 버립니다.</p>${g.shopMessage?`<aside class="shop-result" role="status">${esc(g.shopMessage)}</aside>`:''}<div class="shop-list" aria-label="판매 목록">${list||'<p class="shop-empty">판매할 수 있는 장비나 소모품이 없습니다.</p>'}</div><details class="shop-info"><summary>판매 안내</summary><p>장착한 장비는 장비 화면에서 해제한 뒤 판매할 수 있습니다. 유해·성장 장비·경험·스탠드·영구 처치는 매입하지 않습니다. 정비 비용은 매입가에 포함하지 않습니다. 판매는 행동을 소모하지 않으며, 배운 기술 카드는 유지됩니다.</p></details>`;
 }
 const list=visible.map(r=>{
  const it=data.items[r.item],gear=['gear','rare'].includes(r.kind),old=gear&&g.equipment[it.slot],own=r.kind==='supply'?g.economy.stock[r.item]||0:0;
  const place=gear?data.equipmentSlots[it.slot]+(it.slot==='charm'?' · '+it.wear:''):r.kind==='heal'?'치료':r.kind==='tune'?'장착 무기':r.kind==='service'?'정비 서비스':'소모품';
  const note=gear?'현재: '+(old?itemName(data,g,old):'장착 없음'):r.kind==='supply'?'보유 '+own+' / '+data.economy.supplies[r.item].carry:'';
  const label=r.kind==='gear'?'구입·장착':r.kind==='rare'?'구입·보관':r.kind==='tune'?'정비':r.kind==='heal'?'치료':r.kind==='service'?'이용':'구입';
  return `<article class="shop-row" data-item="${esc(r.id)}"><div class="shop-copy"><div class="shop-item-title"><b>${esc(r.n)}</b><span class="slot-tag">${esc(place)}</span></div><p>${esc(r.d.replace(/ · 보유 \d+\/\d+$/,''))}</p>${gear&&it.weaponCard?`<small class="shop-note">기술 카드 · ${esc(data.cards[it.weaponCard].n)}${race.lockedDeck()?' · 전용 덱은 $'+race.cardCash()+'로 환전':' · 보관함으로 지급'}</small>`:''}${note?`<small class="shop-note">${esc(note)}</small>`:''}${r.reason?`<small class="shop-status">${esc(r.reason)}</small>`:''}</div><div class="shop-buy">${btn('buy:'+r.id,`<b>$${r.price}</b><span>${label}</span>`,'purchase',`${r.reason?'disabled':''} aria-label="${esc(r.n)} ${label} $${r.price}" title="${esc(r.reason||label)}"`)}${own?btn('supply:'+r.item,'사용','text-action',race.supplyInfo(r.item).ok?'':'disabled'):''}</div></article>`;
 }).join('');
 return `<div class="shop-topline"><span>${race.stage()}구간 · ${black?'한정 진열':'대회 보급소'}</span><strong>$${g.ch.money}</strong></div>${black?'':'<p class="shop-provider">스피드왜건 석유회사 · 윈체스터 총포사 후원 물자</p>'}${black?'':`<p class="shop-provider">이번 진열 · 무기 ${rows.filter(r=>r.kind==='gear'&&data.items[r.item]?.slot==='weapon').length}종 · 몸통 ${rows.filter(r=>r.kind==='gear'&&data.items[r.item]?.slot==='armor').length}종 · 보조 ${rows.filter(r=>r.kind==='gear'&&data.items[r.item]?.slot==='charm').length}종</p>`}${tabs}${g.shopMessage?`<aside class="shop-result" role="status">${esc(g.shopMessage)}</aside>`:''}<div class="shop-list" aria-label="${black?'희귀 장비':{supplies:'물자',gear:'장비',service:'정비'}[tab]} 목록">${list||'<p class="shop-empty">현재 구입할 수 있는 품목이 없습니다.</p>'}</div><details class="shop-info"><summary>거래 안내</summary><p>${black?'구입한 희귀 장비는 보관함으로 받습니다. 장비 화면에서 직접 장착할 수 있습니다. 이번 방문의 진열은 유지됩니다.':'구입한 장비는 무기·몸통·보조의 해당 칸에 장착하고 이전 장비는 보관합니다. 거래와 정비는 행동을 소모하지 않습니다. 다음 보급 기회는 '+data.economy.market.every+'행동 후입니다.'}</p></details>`;
}
export function supplyButtons({data,race,esc,btn}){
 const stock=race.state.economy.stock,owned=Object.entries(data.economy.supplies).filter(([id])=>stock[id]>0);
 return owned.length?`<div class="combat-supplies" role="group" aria-label="전투 보급품 · 턴당 하나"><span>보급품 · 턴당 1개</span>${owned.map(([id,it])=>btn('supply:'+id,`${esc(it.n)}<small>${stock[id]}개</small>`,'',`${race.supplyInfo(id).ok?'':'disabled'} title="${esc(it.d)}"`)).join('')}</div>`:'';
}
